<script setup lang="ts">
import { onMounted, ref } from "vue";
import { CalendarClock, Play, Pause, RefreshCw } from "@lucide/vue";
import { useScheduleStore } from "@/stores/scheduleStore";
import { useWorkspaceStore } from "@/stores/workspaceStore";

const store=useScheduleStore(), workspaces=useWorkspaceStore();
const name=ref(""), goal=ref(""), recurrence=ref<"daily"|"weekly">("weekly"), weekday=ref(0), time=ref("09:00"), workspaceId=ref("");
const taskKind=ref<"knowledge_report"|"source_report">("source_report"), sourceQuery=ref("AI agents"), sourceMaxResults=ref(5);
onMounted(async()=>{await Promise.all([store.load(),workspaces.loadWorkspaces()]);workspaceId.value=workspaces.selectedWorkspaceId||""});
async function submit(){const [hour,minute]=time.value.split(":").map(Number);const ok=await store.create({name:name.value,user_goal:goal.value,recurrence:recurrence.value,timezone:"Asia/Shanghai",hour,minute,weekday:recurrence.value==="weekly"?weekday.value:undefined,workspace_id:workspaceId.value||undefined,task_kind:taskKind.value,source_query:taskKind.value==="source_report"?sourceQuery.value:undefined,source_max_results:taskKind.value==="source_report"?sourceMaxResults.value:undefined});if(ok){name.value="";goal.value=""}}
const weekdays=["周一","周二","周三","周四","周五","周六","周日"];
function scheduleText(item:any){return item.recurrence==="daily"?`每天 ${String(item.hour).padStart(2,"0")}:${String(item.minute).padStart(2,"0")}`:`每${weekdays[item.weekday]} ${String(item.hour).padStart(2,"0")}:${String(item.minute).padStart(2,"0")}`}
</script>

<template><div class="h-full overflow-auto"><header class="border-b border-[var(--color-border)] px-5 py-4"><div class="flex items-center justify-between"><div class="flex items-center gap-2"><CalendarClock :size="18"/><h1 class="font-medium">定期任务</h1></div><button class="flex items-center gap-1 rounded border bg-white px-2.5 py-1.5 text-xs" @click="store.load"><RefreshCw :size="13"/>刷新</button></div><p class="mt-1 text-xs text-[var(--color-muted)]">来源报告可定期检索 arXiv、过滤已收录文献并写入 Obsidian；不会自动下载 PDF。</p></header><main class="mx-auto max-w-4xl space-y-5 p-5"><p v-if="store.error" class="rounded border border-red-200 bg-red-50 p-3 text-xs text-red-600">{{store.error}}</p><section class="space-y-3 rounded-lg border bg-white p-4"><h2 class="text-sm font-medium">新建计划</h2><div class="grid gap-3 sm:grid-cols-2"><select v-model="taskKind" class="rounded border px-3 py-2 text-sm"><option value="source_report">arXiv 来源报告</option><option value="knowledge_report">普通知识库报告</option></select><input v-model="name" maxlength="200" class="w-full rounded border px-3 py-2 text-sm" placeholder="计划名称，例如：每周 AI 技术报告"/></div><div v-if="taskKind==='source_report'" class="grid gap-3 sm:grid-cols-[1fr_10rem]"><input v-model="sourceQuery" maxlength="300" class="rounded border px-3 py-2 text-sm" placeholder="arXiv 检索词，例如 AI agents"/><select v-model.number="sourceMaxResults" class="rounded border px-3 py-2 text-sm"><option v-for="n in 10" :key="n" :value="n">最多 {{n}} 篇</option></select></div><textarea v-model="goal" maxlength="10000" class="min-h-28 w-full rounded border px-3 py-2 text-sm" placeholder="说明报告关注重点、总结结构和输出要求"></textarea><div class="grid gap-3 sm:grid-cols-4"><select v-model="recurrence" class="rounded border px-3 py-2 text-sm"><option value="weekly">每周</option><option value="daily">每天</option></select><select v-if="recurrence==='weekly'" v-model="weekday" class="rounded border px-3 py-2 text-sm"><option v-for="(day,i) in weekdays" :key="day" :value="i">{{day}}</option></select><input v-model="time" type="time" class="rounded border px-3 py-2 text-sm"/><select v-model="workspaceId" class="rounded border px-3 py-2 text-sm"><option value="">默认工作区</option><option v-for="ws in workspaces.activeWorkspaces" :key="ws.id" :value="ws.id">{{workspaces.displayName(ws)}}</option></select></div><p class="text-xs text-[var(--color-muted)]">授权范围：只读检索固定 arXiv 查询，以及向 Jarvis 专用 Vault 新建报告。PDF 下载仍需单独确认。</p><button class="rounded bg-blue-600 px-4 py-2 text-xs text-white disabled:opacity-50" :disabled="store.saving||!name.trim()||!goal.trim()||(taskKind==='source_report'&&!sourceQuery.trim())" @click="submit">创建定期任务</button></section><section><h2 class="mb-2 text-sm font-medium">计划 {{store.items.length}}</h2><div v-if="!store.items.length" class="rounded border border-dashed p-6 text-center text-xs text-[var(--color-muted)]">暂无定期任务</div><div v-else class="space-y-2"><article v-for="item in store.items" :key="item.id" class="rounded border bg-white p-4"><div class="flex items-start justify-between gap-3"><div><div class="flex items-center gap-2"><p class="text-sm font-medium">{{item.name}}</p><span class="rounded bg-blue-50 px-2 py-0.5 text-[11px] text-blue-700">{{item.task_kind==='source_report'?'arXiv 来源报告':'知识库报告'}}</span></div><p class="mt-1 text-xs text-[var(--color-muted)]">{{scheduleText(item)}} · 下次 {{new Date(item.next_run_at).toLocaleString()}}</p><p v-if="item.source_policy.query" class="mt-1 text-xs text-[var(--color-muted)]">检索：{{item.source_policy.query}} · 最多 {{item.source_policy.max_results}} 篇</p><p class="mt-2 line-clamp-2 text-xs">{{item.user_goal}}</p><p v-if="item.last_task_id" class="mt-2 text-xs text-[var(--color-muted)]">最近 Task：{{item.last_task_id}}</p></div><span class="rounded px-2 py-1 text-xs" :class="item.status==='active'?'bg-green-50 text-green-700':'bg-gray-100 text-gray-600'">{{item.status==='active'?'运行中':'已暂停'}}</span></div><div class="mt-3 flex gap-2"><button class="flex items-center gap-1 rounded border px-2.5 py-1.5 text-xs" :disabled="store.saving" @click="store.trigger(item)"><Play :size="12"/>立即运行</button><button class="flex items-center gap-1 rounded border px-2.5 py-1.5 text-xs" :disabled="store.saving" @click="store.toggle(item)"><Pause :size="12"/>{{item.status==='active'?'暂停':'恢复'}}</button></div></article></div></section></main></div></template>
